CREATE TABLE app_user (id UUID PRIMARY KEY, email VARCHAR(200) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','EMPLOYEE')), enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE app_session (token_hash VARCHAR(64) PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id), expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX session_expiry ON app_session(expires_at);
CREATE TABLE customer (id UUID PRIMARY KEY, name VARCHAR(160) NOT NULL, phone VARCHAR(20) UNIQUE NOT NULL, category VARCHAR(80) NOT NULL DEFAULT '', tags VARCHAR(500) NOT NULL DEFAULT '', unsubscribed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE consent_record (id UUID PRIMARY KEY, customer_id UUID NOT NULL REFERENCES customer(id), granted BOOLEAN NOT NULL, scope VARCHAR(40) NOT NULL CHECK(scope = 'MARKETING'), source VARCHAR(200) NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX consent_customer ON consent_record(customer_id,recorded_at);
CREATE TABLE dish (id UUID PRIMARY KEY, name VARCHAR(160) NOT NULL, description VARCHAR(2000) NOT NULL, category VARCHAR(80) NOT NULL, price BIGINT NOT NULL CHECK(price >= 0 AND price <= 100000000), available BOOLEAN NOT NULL, image_url VARCHAR(500), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE daily_menu (id UUID PRIMARY KEY, menu_date DATE NOT NULL, title VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE menu_item (menu_id UUID NOT NULL REFERENCES daily_menu(id), dish_id UUID NOT NULL REFERENCES dish(id), name VARCHAR(160) NOT NULL, price BIGINT NOT NULL CHECK(price >= 0), PRIMARY KEY(menu_id,dish_id));
CREATE TABLE customer_order (id UUID PRIMARY KEY, customer_id UUID NOT NULL REFERENCES customer(id), status VARCHAR(30) NOT NULL CHECK(status IN ('PENDING','CONFIRMED','PREPARING','READY','DELIVERED','CANCELLED')), fulfillment VARCHAR(20) NOT NULL CHECK(fulfillment IN ('PICKUP','DELIVERY')), address VARCHAR(1000) NOT NULL, instructions VARCHAR(1000) NOT NULL, total BIGINT NOT NULL CHECK(total >= 0), paid BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX order_created ON customer_order(created_at);
CREATE TABLE order_item (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES customer_order(id), dish_id UUID NOT NULL REFERENCES dish(id), name VARCHAR(160) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 100), unit_price BIGINT NOT NULL CHECK(unit_price >= 0));
CREATE TABLE order_status_history (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES customer_order(id), status VARCHAR(30) NOT NULL, actor UUID REFERENCES app_user(id), changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE conversation (id UUID PRIMARY KEY, customer_id UUID UNIQUE NOT NULL REFERENCES customer(id), status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')), unread INTEGER NOT NULL DEFAULT 0 CHECK(unread >= 0), last_inbound_at TIMESTAMP WITH TIME ZONE, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE message (id UUID PRIMARY KEY, conversation_id UUID NOT NULL REFERENCES conversation(id), whatsapp_id VARCHAR(300) UNIQUE, request_key UUID UNIQUE, direction VARCHAR(10) NOT NULL CHECK(direction IN ('IN','OUT')), type VARCHAR(30) NOT NULL, body VARCHAR(10000) NOT NULL, media_id VARCHAR(300), status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','ACCEPTED','SENT','DELIVERED','READ','FAILED','UNKNOWN','RECEIVED')), source VARCHAR(30) NOT NULL DEFAULT 'CLOUD_API', error_code VARCHAR(80), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX message_conversation ON message(conversation_id,created_at);
CREATE TABLE message_status_event (event_key VARCHAR(64) PRIMARY KEY, whatsapp_id VARCHAR(300) NOT NULL, status VARCHAR(30) NOT NULL, event_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE webhook_event (event_key VARCHAR(64) PRIMARY KEY, field VARCHAR(80) NOT NULL, payload TEXT NOT NULL, state VARCHAR(30) NOT NULL, error_code VARCHAR(100), received_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE campaign (id UUID PRIMARY KEY, menu_id UUID NOT NULL REFERENCES daily_menu(id), template_name VARCHAR(512) NOT NULL, language VARCHAR(20) NOT NULL, preview TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE campaign_recipient (id UUID PRIMARY KEY, campaign_id UUID NOT NULL REFERENCES campaign(id), customer_id UUID NOT NULL REFERENCES customer(id), message_id UUID REFERENCES message(id), status VARCHAR(20) NOT NULL DEFAULT 'PENDING', error_code VARCHAR(100), UNIQUE(campaign_id,customer_id));
CREATE TABLE restaurant_settings (id INTEGER PRIMARY KEY CHECK(id=1), name VARCHAR(160) NOT NULL, timezone VARCHAR(80) NOT NULL DEFAULT 'Africa/Ouagadougou', currency VARCHAR(10) NOT NULL DEFAULT 'XOF');
INSERT INTO restaurant_settings(id,name) VALUES(1,'Restaurant Connect BF');
CREATE TABLE audit_log (id UUID PRIMARY KEY, actor UUID REFERENCES app_user(id), action VARCHAR(100) NOT NULL, target VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sync_run (id UUID PRIMARY KEY, field VARCHAR(80) NOT NULL, state VARCHAR(30) NOT NULL, details VARCHAR(1000) NOT NULL, received_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
